// Prueft Eingaben und leitet den Suchzeitraum ab. Der Event-Type kommt
// IMMER aus der Kunden-Config, nie aus den Agent-Parametern.
const e = $input.first().json;
const p = e.params || {};
const c = e.config || {};

const zone = c.zeitzone || 'Europe/Berlin';
const heute = $now.setZone(zone);

function istDatum(w) { return /^\d{4}-\d{2}-\d{2}/.test(String(w || '').trim()); }

// Startpunkt: gewuenschter Zeitraum, sonst heute. Nie in der Vergangenheit.
let von = istDatum(p.zeitraum_von) ? String(p.zeitraum_von).slice(0, 10) : heute.toFormat('yyyy-MM-dd');
if (von < heute.toFormat('yyyy-MM-dd')) von = heute.toFormat('yyyy-MM-dd');

// Das Ende haengt am Start, nicht an heute: fragt jemand nach Dezember, wird
// auch im Dezember gesucht und nicht im naechsten Termin-Nichts.
const vonDt = DateTime.fromISO(von, { zone: zone });
let bis = istDatum(p.zeitraum_bis) ? String(p.zeitraum_bis).slice(0, 10)
                                   : vonDt.plus({ days: 14 }).toFormat('yyyy-MM-dd');
// Deckel, damit eine unsinnige Anfrage nicht ein ganzes Jahr abfragt.
const maxBis = vonDt.plus({ days: 60 }).toFormat('yyyy-MM-dd');
if (bis > maxBis) bis = maxBis;

let fehler = '';
if (!c.cal_event_type_id) fehler = 'kalender nicht konfiguriert';
  else if (String(c.kalender_typ || 'calcom') !== 'calcom') fehler = 'kalender nicht unterstuetzt';
else if (bis < von) fehler = 'zeitraum ungueltig';

return [{ json: Object.assign({}, e, {
  von: von, bis: bis, terminart: String(p.terminart || ''), fehler: fehler,
}) }];

const ktx = $('Eingaben pruefen').first().json;
// Vereinheitlicht die Antwort. Kein Sub-Workflow gibt je etwas anderes
// zurueck als { success, data, message } - darauf bauen die Retell-Agenten
// ihre Erfolgs- und Fehlerzweige auf.
function antwort(success, data, message) {
  return { success: !!success, data: data || {}, message: String(message || '') };
}

if (ktx.fehler) return [{ json: antwort(false, {}, ktx.fehler) }];

const r = $input.first().json || {};
if (r.error) return [{ json: antwort(false, {}, 'kalender nicht erreichbar') }];
if (Number(r.statusCode) >= 400) {
  return [{ json: antwort(false, {}, 'kalender antwortet mit fehler ' + r.statusCode) }];
}

const daten = (r.body && r.body.data) || {};
// Cal.com liefert { "2026-08-01": [{ start: "..." }], ... }. Hoechstens zwei
// Vorschlaege pro Tag, damit der Agent verschiedene Tage anbietet statt
// fuenfmal denselben Vormittag.
const auswahl = [];
let gesamt = 0;
Object.keys(daten).sort().forEach(tag => {
  const slots = daten[tag] || [];
  gesamt += slots.length;
  slots.slice(0, 2).forEach(s => {
    if (s && s.start && auswahl.length < 5) auswahl.push(s.start);
  });
});

if (gesamt === 0) {
  return [{ json: antwort(true, { verfuegbare_zeiten: [], anzahl: 0 },
    'keine freien termine im zeitraum') }];
}

return [{ json: antwort(true, {
  verfuegbare_zeiten: auswahl,
  anzahl: gesamt,
  zeitzone: ktx.config.zeitzone,
}, 'termine gefunden') }];
